var t=[{title:`Co dělá která oblast`,text:`Hrudní páteř je střední část zad a umožňuje otáčení a extenzi. Komplex ramene zahrnuje kulový kloub a lopatku klouzající po hrudním koši. Dosah nad hlavu závisí na spolupráci několika oblastí, takže testuje víc než flexibilitu ramenního kloubu.`},{title:`Zkoumejte pohodlný pohyb`,text:`Cvik open book jemně otáčí horní polovinu těla, zatímco kyčle zůstávají poměrně v klidu. Kontrolované kroužení pažemi procvičuje pohyb ramen a cat-cow pohybuje páteří do flexe a extenze v klidném tempu. Pohybujte se pomalu, dýchejte normálně a nevynucujte koncovou polohu.`},{title:`Mobilita ve vašich cvicích`,text:`Tlak nad hlavou může působit plynuleji, když se žebra, lopatky a paže pohybují společně. U přítahů nechte lopatky pohybovat se přirozeně; nemusíte je držet staženě celou dobu. Míříte na plynulou kontrolu ve zvoleném cviku. Neexistuje jediné strnulé držení těla, které by musel každý kopírovat.`},{title:`Mobilita plus síla`,text:`Lehké tlaky, wall slides, přítahy a kontrolované nošení zátěže budují použitelný rozsah a koordinaci společně. Samotné protahování může zlepšit pasivní flexibilitu, aniž by vám dalo plnou kontrolu pod zátěží. Pokud cvik působí nestabilně nebo nepohodlně, změňte úchop, úhel nebo rozsah pohybu.`},{title:`Použití v TrainUp`,text:`Pokud vám práce nad hlavou vadí rameni, přidejte rameno jako omezení v Profilu s poznámkou. Plán vybírá jen cviky, které odpovídají vašim omezením. Při nové, přetrvávající nebo se zhoršující bolesti ramene vyhledejte lékaře nebo fyzioterapeuta místo spoléhání na obecné cviky mobility.`}];var n=[{label:`ACE 2026: mobilita versus flexibilita`,url:`https://www.acefitness.org/continuing-education/certified/may-2026/9119/mobility-vs-flexibility-why-the-difference-matters-for-movement-and-performance/`},{label:`ACE 2026: praktické rady k protahování`,url:`https://www.acefitness.org/continuing-education/certified/april-2026/9104/new-expert-guidance-on-stretching-what-belongs-in-your-programs/?authorScope=80`},{label:`Knihovna cviků ACE`,url:`https://www.acefitness.org/resources/everyone/exercise-library/`}];var a={sections:t,sources:n};export{a as default,t as sections,n as sources};